style.css:
@-moz-document domain("roblox.com") {
/* Background */
  body {
    background: url("https://i.imgur.com/AiKHf6M.jpeg") no-repeat center center fixed !important;
    background-size: cover !important;
  }

  /* Frosted glass effect */
  .container, .game-card-container, .section, .content, .theme-dark, .avatar-card-container, .header, .footer {
    background: rgba(255, 255, 255, 0.1) !important;
    backdrop-filter: blur(18px) !important;
    -webkit-backdrop-filter: blur(18px) !important;
    border-radius: 18px !important;
    box-shadow: 0 4px 24px rgba(0, 0, 0, 0.2) !important;
  }

  /* Navbar */
  .navbar {
    background: rgba(255, 255, 255, 0.15) !important;
    backdrop-filter: blur(14px) !important;
    border-bottom: 1px solid rgba(255,255,255,0.15) !important;
  }

  /* Blue frosted Play button */
  .play-button, .btn-primary-play {
    background: rgba(0, 122, 255, 0.3) !important;
    color: white !important;
    backdrop-filter: blur(10px) !important;
    border: none !important;
    border-radius: 12px !important;
  }

  /* Sidebar */
  .left-col, .sidebar {
    background: rgba(255, 255, 255, 0.05) !important;
    backdrop-filter: blur(12px) !important;
    border-radius: 16px !important;
  }

  /* Profile icon override */
  .avatar-card-image, .avatar-headshot {
    background-image: url("https://chat.openai.com/mnt/data/69e0eebb-7e25-453a-b971-a5263d52da74.png") !important;
    background-size: cover !important;
    border-radius: 50% !important;
  }

  /* Font */
  * {
    font-family: "Segoe UI", sans-serif !important;
  }

  /* Rounded edges and spacing */
  .game-card, .game-tile, .card, .media-card, .recommendation, .avatar-card {
    border-radius: 16px !important;
    padding: 8px !important;
  }
}
